// Worker shim that loads the official qr-scanner worker from unpkg CDN.
// This allows the client-side QrScanner to function without bundling the worker.
// For offline or pinned versions, copy the worker from node_modules/qr-scanner/qr-scanner-worker.min.js
importScripts('https://unpkg.com/qr-scanner@1.5.2/qr-scanner-worker.min.js');
